select p.race_date,p.track,p.race_no,k.key,jsonb_typeof(p.payload->'audit'->k.key) as value_type,length((p.payload->'audit'->k.key)::text) as full_chars,left((p.payload->'audit'->k.key)::text,5000) as value_excerpt from public.official_predictions p join public.official_races o using(race_date,track,race_no) cross join lateral (values ('independent_score_method'),('manual_score_breakdown')) k(key) where o.circuit='JRA' and p.status='FROZEN' and o.race_date between '2026-10-17' and '2026-11-15' and p.payload->'audit' ? k.key order by p.race_date,p.track,p.race_no,k.key limit 4;
